import React, { useState, useEffect } from 'react';
import './styles/globals.css';
import LoginPage from './pages/LoginPage';
import MainPage from './pages/MainPage';
import OwlyIntro from './pages/OwlyIntro';
import OwlyChat from './pages/OwlyChat';
import UserChat from './pages/UserChat';
import { getToken, apiMe, setCurrentUser, clearToken, clearCurrentUser } from './services/api';
import { connectSocket, disconnectSocket } from './services/socket';

type AppPage = 'login' | 'main' | 'owly-intro' | 'owly-chat' | 'user-chat';

const App: React.FC = () => {
  const [page, setPage] = useState<AppPage>('login');
  const [authChecked, setAuthChecked] = useState(false);

  // On mount: check if there's a valid saved token
  useEffect(() => {
    const token = getToken();
    if (!token) {
      setAuthChecked(true);
      return;
    }
    apiMe()
      .then(({ user }) => {
        setCurrentUser(user);
        connectSocket();
        setPage('main');
      })
      .catch(() => {
        clearToken();
        clearCurrentUser();
      })
      .finally(() => setAuthChecked(true));
  }, []);

  const handleLogin = () => {
    connectSocket();
    setPage('main');
  };

  const handleLogout = () => {
    disconnectSocket();
    clearToken();
    clearCurrentUser();
    setPage('login');
  };

  const handleNavigate = (target: string) => {
    if (target === 'owly') setPage('owly-intro');
    else if (target === 'chats') setPage('user-chat');
    else if (target === 'main') setPage('main');
  };

  if (!authChecked) return null; // Avoid flash before token check

  switch (page) {
    case 'login':
      return <LoginPage onLogin={handleLogin} />;
    case 'owly-intro':
      return <OwlyIntro onContinue={() => setPage('owly-chat')} onBack={() => setPage('main')} />;
    case 'owly-chat':
      return <OwlyChat onBack={() => setPage('owly-intro')} />;
    case 'user-chat':
      return <UserChat onBack={() => setPage('main')} />;
    case 'main':
    default:
      return <MainPage onNavigate={handleNavigate as any} onBack={handleLogout} />;
  }
};

export default App;
